    contract: HIA_JSDOC_UMBRELLA_CONTRACT,
    contractVersion: HIA_JSDOC_UMBRELLA_CONTRACT_VERSION,
    jsdoc: {
      package: JSDOC_PACKAGE,
      version: JSDOC_VERSION
